--- apps/worker/src/services/achievement-calculation.ts	
+++ apps/worker/src/services/achievement-calculation.ts	
@@ -1,291 +1,304 @@
 import { sql, inArray, eq } from "drizzle-orm";
 import type { DrizzleDB } from "../db";
 import { user } from "../db/schema/auth-schema";
 import {
 	matchPlayer,
 	seasonPlayer,
 	playerAchievement,
 	player,
 	guest,
 	type achievementType,
 } from "../db/schema/league-schema";

 type AchievementType = (typeof achievementType)[number];

-type AchievementQueueMessage = {
+export type AchievementQueueMessage = {
 	seasonPlayerIds: string[];
+	leagueSlug: string;
+	seasonSlug: string;
 };

 export type NewAchievement = {
 	playerId: string;
 	name: string;
 	image: string | null;
 	type: AchievementType;
 };

-export type { AchievementQueueMessage };
+export function buildAchievementUnlockEvents(newAchievements: NewAchievement[]): Array<{
+	type: "achievement:unlock";
+	data: { player: { id: string; name: string; image: string | null }; type: AchievementType };
+}> {
+	return newAchievements.map((a) => ({
+		type: "achievement:unlock",
+		data: {
+			player: { id: a.playerId, name: a.name, image: a.image },
+			type: a.type,
+		},
+	}));
+}

 const streakThresholds: Partial<Record<AchievementType, number>> = {
 	"5_win_streak": 5,
 	"10_win_streak": 10,
 	"15_win_streak": 15,
 	"3_win_loss_redemption": 3,
 	"5_win_loss_redemption": 5,
 	"8_win_loss_redemption": 8,
 	"5_clean_sheet_streak": 5,
 	"10_clean_sheet_streak": 10,
 	"15_clean_sheet_streak": 15,
 	"3_goals_5_games": 3,
 	"5_goals_5_games": 5,
 	"8_goals_5_games": 8,
 };

 export async function calculateAchievements(
 	db: DrizzleDB,
 	seasonPlayerIds: string[]
 ): Promise<NewAchievement[]> {
 	if (seasonPlayerIds.length === 0) return [];

 	// Single query: get all match results for all players, ordered by creation time
 	const allMatchResults = await db
 		.select({
 			seasonPlayerId: matchPlayer.seasonPlayerId,
 			result: matchPlayer.result,
 			homeTeam: matchPlayer.homeTeam,
 			matchId: matchPlayer.matchId,
 			createdAt: matchPlayer.createdAt,
 		})
 		.from(matchPlayer)
 		.where(inArray(matchPlayer.seasonPlayerId, seasonPlayerIds))
 		.orderBy(matchPlayer.createdAt);

 	// Single query: get goals conceded per match for each player
 	// Goals conceded = sum of opponent goals in the same match
 	// For a home player, conceded goals = match.awayScore; for away player = match.homeScore
 	// We can derive this from the match scores via match table
 	const matchIds = [...new Set(allMatchResults.map((r) => r.matchId))];

 	const goalsConcededMap = new Map<string, Map<string, number>>();
 	if (matchIds.length > 0) {
 		const goalsConceded = await db.all<{
 			seasonPlayerId: string;
 			matchId: string;
 			goalsConceded: number;
 		}>(sql`
 			SELECT 
 				mp.season_player_id as seasonPlayerId,
 				mp.match_id as matchId,
 				CASE WHEN mp.home_team = 1 THEN m.away_score ELSE m.home_score END as goalsConceded
 			FROM match_player mp
 			INNER JOIN match m ON mp.match_id = m.id
 			WHERE mp.season_player_id IN (${sql.join(
 				seasonPlayerIds.map((id) => sql`${id}`),
 				sql`, `
 			)})
 		`);

 		for (const row of goalsConceded) {
 			let playerMap = goalsConcededMap.get(row.seasonPlayerId);
 			if (!playerMap) {
 				playerMap = new Map();
 				goalsConcededMap.set(row.seasonPlayerId, playerMap);
 			}
 			playerMap.set(row.matchId, row.goalsConceded);
 		}
 	}

 	// Single query: get last 5 matches goals scored per player
 	// Goals scored for home player = match.homeScore; for away = match.awayScore
 	const last5GoalsMap = new Map<string, number[]>();
 	if (matchIds.length > 0) {
 		const last5Goals = await db.all<{
 			seasonPlayerId: string;
 			goalsScored: number;
 			rn: number;
 		}>(sql`
 			SELECT seasonPlayerId, goalsScored, rn FROM (
 				SELECT 
 					mp.season_player_id as seasonPlayerId,
 					CASE WHEN mp.home_team = 1 THEN m.home_score ELSE m.away_score END as goalsScored,
 					ROW_NUMBER() OVER (PARTITION BY mp.season_player_id ORDER BY mp.created_at DESC) as rn
 				FROM match_player mp
 				INNER JOIN match m ON mp.match_id = m.id
 				WHERE mp.season_player_id IN (${sql.join(
 					seasonPlayerIds.map((id) => sql`${id}`),
 					sql`, `
 				)})
 			)
 			WHERE rn <= 5
 			ORDER BY seasonPlayerId, rn
 		`);

 		for (const row of last5Goals) {
 			let goals = last5GoalsMap.get(row.seasonPlayerId);
 			if (!goals) {
 				goals = [];
 				last5GoalsMap.set(row.seasonPlayerId, goals);
 			}
 			goals.push(row.goalsScored);
 		}
 	}

 	// Resolve seasonPlayerId -> player info for achievement storage + broadcast
 	const playerInfo = await db
 		.select({
 			seasonPlayerId: seasonPlayer.id,
 			playerId: seasonPlayer.playerId,
 			name: sql<string>`COALESCE(${user.name}, ${guest.displayName})`.as("name"),
 			image: user.image,
 		})
 		.from(seasonPlayer)
 		.innerJoin(player, eq(seasonPlayer.playerId, player.id))
 		.leftJoin(user, eq(player.userId, user.id))
 		.leftJoin(guest, eq(player.guestId, guest.id))
 		.where(inArray(seasonPlayer.id, seasonPlayerIds));

 	const seasonToPlayerMap = new Map(playerInfo.map((p) => [p.seasonPlayerId, p]));

 	// Group match results by season player
 	const resultsByPlayer = new Map<string, typeof allMatchResults>();
 	for (const r of allMatchResults) {
 		let playerResults = resultsByPlayer.get(r.seasonPlayerId);
 		if (!playerResults) {
 			playerResults = [];
 			resultsByPlayer.set(r.seasonPlayerId, playerResults);
 		}
 		playerResults.push(r);
 	}

 	// Calculate achievements per player
 	const achievementsToInsert: NewAchievement[] = [];

 	for (const spId of seasonPlayerIds) {
 		const info = seasonToPlayerMap.get(spId);
 		if (!info) continue;

 		const earned: AchievementType[] = [];
 		const matches = resultsByPlayer.get(spId) || [];
 		const concededForPlayer = goalsConcededMap.get(spId) || new Map();

 		// Check redemption achievements (pattern matching on result string)
 		checkRedemptionAchievements(earned, matches);

 		// Check goals scored in last 5 games
 		const lastFiveGoals = last5GoalsMap.get(spId) || [];
 		checkGoalsScoredStreak(earned, lastFiveGoals);

 		// Check win streaks and clean sheet streaks
 		let currentWinStreak = 0;
 		let currentCleanSheetStreak = 0;

 		for (const m of matches) {
 			if (m.result === "W") {
 				currentWinStreak++;
 			} else {
 				currentWinStreak = 0;
 			}

 			checkStreakAchievement(earned, currentWinStreak, [
 				"5_win_streak",
 				"10_win_streak",
 				"15_win_streak",
 			]);

 			const goalsConceded = concededForPlayer.get(m.matchId) ?? -1;
 			if (goalsConceded === 0) {
 				currentCleanSheetStreak++;
 				checkStreakAchievement(earned, currentCleanSheetStreak, [
 					"5_clean_sheet_streak",
 					"10_clean_sheet_streak",
 					"15_clean_sheet_streak",
 				]);
 			} else {
 				currentCleanSheetStreak = 0;
 			}
 		}

 		for (const achievement of earned) {
 			achievementsToInsert.push({
 				playerId: info.playerId,
 				name: info.name,
 				image: info.image,
 				type: achievement,
 			});
 		}
 	}

 	// Filter out achievements already earned (idempotent, no re-broadcast)
 	const playerIds = [...new Set(achievementsToInsert.map((a) => a.playerId))];
 	const existing = playerIds.length
 		? await db
 				.select({ playerId: playerAchievement.playerId, type: playerAchievement.type })
 				.from(playerAchievement)
 				.where(inArray(playerAchievement.playerId, playerIds))
 		: [];
 	const existingSet = new Set(existing.map((e) => `${e.playerId}:${e.type}`));
 	const newAchievements = achievementsToInsert.filter(
 		(a) => !existingSet.has(`${a.playerId}:${a.type}`)
 	);

 	if (newAchievements.length > 0) {
 		const now = new Date();
 		await db
 			.insert(playerAchievement)
 			.values(
 				newAchievements.map((a) => ({
 					id: crypto.randomUUID(),
 					playerId: a.playerId,
 					type: a.type,
 					createdAt: now,
 					updatedAt: now,
 				}))
 			)
 			.onConflictDoNothing();
 	}

 	return newAchievements;
 }

 function checkGoalsScoredStreak(earned: AchievementType[], lastFiveGoals: number[]) {
 	if (lastFiveGoals.length < 5) return;

 	if (lastFiveGoals.every((n) => n >= 8)) {
 		earned.push("8_goals_5_games", "5_goals_5_games", "3_goals_5_games");
 	} else if (lastFiveGoals.every((n) => n >= 5)) {
 		earned.push("5_goals_5_games", "3_goals_5_games");
 	} else if (lastFiveGoals.every((n) => n >= 3)) {
 		earned.push("3_goals_5_games");
 	}
 }

 function checkStreakAchievement(
 	earned: AchievementType[],
 	currentStreak: number,
 	streakAchievements: AchievementType[]
 ) {
 	for (const achievement of streakAchievements) {
 		if (currentStreak === streakThresholds[achievement] && !earned.includes(achievement)) {
 			earned.push(achievement);
 		}
 	}
 }

 function checkRedemptionAchievements(earned: AchievementType[], matches: { result: string }[]) {
 	const resultString = matches.map((m) => m.result).join("");

 	const redemptionAchievements: AchievementType[] = [
 		"3_win_loss_redemption",
 		"5_win_loss_redemption",
 		"8_win_loss_redemption",
 	];

 	for (const achievement of redemptionAchievements) {
 		const count = streakThresholds[achievement];
 		if (!count) continue;
 		// Pattern: N consecutive losses followed by N consecutive wins
 		const pattern = "L".repeat(count) + "W".repeat(count);
 		if (resultString.includes(pattern)) {
 			earned.push(achievement);
 		}
 	}
 }

Index: apps/worker/src/trpc/router/match-router.ts
===================================================================
--- apps/worker/src/trpc/router/match-router.ts	
+++ apps/worker/src/trpc/router/match-router.ts	
@@ -1,547 +1,551 @@
 import type { TRPCRouterRecord } from "@trpc/server";
 import { TRPCError } from "@trpc/server";
 import { z } from "zod";
 import { createOptionalIdSchema } from "@coding-cowboys/scorebrawl-util/id-util";
 import * as seasonRepository from "../../repositories/season-repository";
 import * as matchRepository from "../../repositories/match-repository";
 import * as seasonPlayerRepository from "../../repositories/season-player-repository";
 import { broadcastSeasonEvent } from "../../routes/sse-router";
 import type { AchievementQueueMessage } from "../../services/achievement-calculation";
 import { seasonProcedure, leagueMemberProcedure } from "../trpc";

 const matchIdSchema = createOptionalIdSchema("match");

 type StreakBroadcastEvent = {
 	type: "streak";
 	data: {
 		playerId: string;
 		playerName: string;
 		playerImage: string | null;
 		streak: number;
 		timestamp: number;
 		isTeam?: boolean;
 	};
 	user: { id: string; name: string };
 };

 function buildStreakBroadcastEvents(
 	streakPlayers: Array<{
 		playerId: string;
 		playerName: string;
 		playerImage: string | null;
 		streak: number;
 	}>,
 	streakTeams: Array<{
 		seasonTeamId: string;
 		teamName: string;
 		teamLogo: string | null;
 		streak: number;
 	}>,
 	user: { id: string; name: string }
 ): StreakBroadcastEvent[] {
 	const events: StreakBroadcastEvent[] = [];
 	const timestamp = Date.now();

 	for (const player of streakPlayers) {
 		events.push({
 			type: "streak",
 			data: {
 				playerId: player.playerId,
 				playerName: player.playerName,
 				playerImage: player.playerImage,
 				streak: player.streak,
 				timestamp,
 			},
 			user,
 		});
 	}

 	for (const team of streakTeams) {
 		events.push({
 			type: "streak",
 			data: {
 				playerId: team.seasonTeamId,
 				playerName: team.teamName,
 				playerImage: team.teamLogo,
 				streak: team.streak,
 				timestamp,
 				isTeam: true,
 			},
 			user,
 		});
 	}

 	return events;
 }

 function broadcastStreakEvents(
 	waitUntil: (promise: Promise<unknown>) => void,
 	env: Pick<Env, "SEASON_SSE">,
 	leagueSlug: string,
 	seasonSlug: string,
 	streakPlayers: Array<{
 		playerId: string;
 		playerName: string;
 		playerImage: string | null;
 		streak: number;
 	}>,
 	streakTeams: Array<{
 		seasonTeamId: string;
 		teamName: string;
 		teamLogo: string | null;
 		streak: number;
 	}>,
 	user: { id: string; name: string }
 ) {
 	const events = buildStreakBroadcastEvents(streakPlayers, streakTeams, user);
 	waitUntil(
 		Promise.all(events.map((event) => broadcastSeasonEvent(env, leagueSlug, seasonSlug, event)))
 	);
 }

 async function finalizeMatchCreation({
 	ctx,
 	seasonSlug,
 	seasonId,
 	createdMatch,
 	seasonPlayerIds,
 }: {
 	ctx: {
 		db: Parameters<typeof seasonPlayerRepository.getStanding>[0]["db"];
 		env: Pick<Env, "SEASON_SSE" | "ACHIEVEMENT_QUEUE">;
 		waitUntil: (promise: Promise<unknown>) => void;
 		organization: { slug: string };
 		authentication: { user: { id: string; name: string } };
 	};
 	seasonSlug: string;
 	seasonId: string;
 	createdMatch: { id: string };
 	seasonPlayerIds: string[];
 }) {
 	const standings = await seasonPlayerRepository.getStanding({
 		db: ctx.db,
 		seasonId,
 	});

 	ctx.waitUntil(
 		broadcastSeasonEvent(ctx.env, ctx.organization.slug, seasonSlug, {
 			type: "match:insert",
 			data: {
 				match: createdMatch,
 				standings,
 			},
 			user: {
 				id: ctx.authentication.user.id,
 				name: ctx.authentication.user.name,
 			},
 		})
 	);

 	const [streakPlayers, streakTeams] = await Promise.all([
 		matchRepository.checkStreakThresholds({
 			db: ctx.db,
 			seasonPlayerIds,
 		}),
 		matchRepository.checkTeamStreakThresholds({
 			db: ctx.db,
 			matchId: createdMatch.id,
 		}),
 	]);

 	broadcastStreakEvents(
 		ctx.waitUntil.bind(ctx),
 		ctx.env,
 		ctx.organization.slug,
 		seasonSlug,
 		streakPlayers,
 		streakTeams,
 		{
 			id: ctx.authentication.user.id,
 			name: ctx.authentication.user.name,
 		}
 	);

 	await ctx.env.ACHIEVEMENT_QUEUE.send({
 		seasonPlayerIds,
+		leagueSlug: ctx.organization.slug,
+		seasonSlug,
 	} satisfies AchievementQueueMessage);

 	return createdMatch;
 }

 export const matchRouter = {
 	createFromFixture: leagueMemberProcedure
 		.input(
 			z.object({
 				seasonSlug: z.string(),
 				homeScore: z.number().int().min(0),
 				awayScore: z.number().int().min(0),
 				fixtureId: z.string(),
 			})
 		)
 		.mutation(async ({ ctx, input }) => {
 			const season = await seasonRepository.getBySlug({
 				db: ctx.db,
 				seasonSlug: input.seasonSlug,
 				leagueId: ctx.organizationId,
 			});

 			if (season.closed) {
 				throw new TRPCError({
 					code: "FORBIDDEN",
 					message: "This season is closed",
 				});
 			}

 			const fixture = await seasonRepository.findFixtureById({
 				db: ctx.db,
 				seasonId: season.id,
 				fixtureId: input.fixtureId,
 			});

 			if (!fixture) {
 				throw new TRPCError({
 					code: "NOT_FOUND",
 					message: "Fixture not found",
 				});
 			}

 			if (fixture.matchId) {
 				throw new TRPCError({
 					code: "CONFLICT",
 					message: "This fixture already has a match",
 				});
 			}

 			const createdMatch = await matchRepository.create({
 				db: ctx.db,
 				input: {
 					seasonId: season.id,
 					homeScore: input.homeScore,
 					awayScore: input.awayScore,
 					homeTeamPlayerIds: [fixture.homePlayerId],
 					awayTeamPlayerIds: [fixture.awayPlayerId],
 					userId: ctx.authentication.user.id,
 				},
 			});

 			await seasonRepository.assignMatchToFixture({
 				db: ctx.db,
 				seasonId: season.id,
 				fixtureId: fixture.id,
 				matchId: createdMatch.id,
 			});

 			const standings = await seasonPlayerRepository.getStanding({
 				db: ctx.db,
 				seasonId: season.id,
 			});

 			ctx.waitUntil(
 				broadcastSeasonEvent(ctx.env, ctx.organization.slug, input.seasonSlug, {
 					type: "match:insert",
 					data: {
 						match: createdMatch,
 						standings,
 					},
 					user: {
 						id: ctx.authentication.user.id,
 						name: ctx.authentication.user.name,
 					},
 				})
 			);

 			const [streakPlayers, streakTeams] = await Promise.all([
 				matchRepository.checkStreakThresholds({
 					db: ctx.db,
 					seasonPlayerIds: [fixture.homePlayerId, fixture.awayPlayerId],
 				}),
 				matchRepository.checkTeamStreakThresholds({
 					db: ctx.db,
 					matchId: createdMatch.id,
 				}),
 			]);

 			broadcastStreakEvents(
 				ctx.waitUntil.bind(ctx),
 				ctx.env,
 				ctx.organization.slug,
 				input.seasonSlug,
 				streakPlayers,
 				streakTeams,
 				{
 					id: ctx.authentication.user.id,
 					name: ctx.authentication.user.name,
 				}
 			);

 			// Dispatch achievement calculation
 			const seasonPlayerIds = [fixture.homePlayerId, fixture.awayPlayerId];
 			await ctx.env.ACHIEVEMENT_QUEUE.send({
 				seasonPlayerIds,
+				leagueSlug: ctx.organization.slug,
+				seasonSlug: input.seasonSlug,
 			} satisfies AchievementQueueMessage);

 			return createdMatch;
 		}),

 	create: leagueMemberProcedure
 		.input(
 			z.object({
 				id: matchIdSchema,
 				seasonSlug: z.string(),
 				homeScore: z.number().int().min(0),
 				awayScore: z.number().int().min(0),
 				homeTeamPlayerIds: z.array(z.string()),
 				awayTeamPlayerIds: z.array(z.string()),
 			})
 		)
 		.mutation(async ({ ctx, input }) => {
 			if (input.homeTeamPlayerIds.length === 0 || input.awayTeamPlayerIds.length === 0) {
 				throw new TRPCError({
 					code: "BAD_REQUEST",
 					message: "Each team must have at least one player",
 				});
 			}

 			if (input.homeTeamPlayerIds.length !== input.awayTeamPlayerIds.length) {
 				throw new TRPCError({
 					code: "BAD_REQUEST",
 					message: "Teams must have equal number of players",
 				});
 			}

 			const comp = await seasonRepository.getBySlug({
 				db: ctx.db,
 				seasonSlug: input.seasonSlug,
 				leagueId: ctx.organizationId,
 			});

 			if (comp.closed) {
 				throw new TRPCError({
 					code: "FORBIDDEN",
 					message: "This season is closed",
 				});
 			}

 			if (input.id) {
 				try {
 					await matchRepository.findById({
 						db: ctx.db,
 						matchId: input.id,
 						seasonId: comp.id,
 					});
 					throw new TRPCError({
 						code: "CONFLICT",
 						message: "A match with this ID already exists",
 					});
 				} catch (error) {
 					if (error instanceof TRPCError) throw error;
 				}
 			}

 			return matchRepository
 				.create({
 					db: ctx.db,
 					input: {
 						id: input.id,
 						seasonId: comp.id,
 						homeScore: input.homeScore,
 						awayScore: input.awayScore,
 						homeTeamPlayerIds: input.homeTeamPlayerIds,
 						awayTeamPlayerIds: input.awayTeamPlayerIds,
 						userId: ctx.authentication.user.id,
 					},
 				})
 				.then(async (createdMatch) =>
 					finalizeMatchCreation({
 						ctx,
 						seasonSlug: input.seasonSlug,
 						seasonId: comp.id,
 						createdMatch,
 						seasonPlayerIds: [...input.homeTeamPlayerIds, ...input.awayTeamPlayerIds],
 					})
 				);
 		}),

 	createOneVn: leagueMemberProcedure
 		.input(
 			z.object({
 				id: matchIdSchema,
 				seasonSlug: z.string(),
 				winnerId: z.string(),
 				loserIds: z.array(z.string()).min(1),
 			})
 		)
 		.mutation(async ({ ctx, input }) => {
 			const comp = await seasonRepository.getBySlug({
 				db: ctx.db,
 				seasonSlug: input.seasonSlug,
 				leagueId: ctx.organizationId,
 			});

 			if (comp.closed) {
 				throw new TRPCError({
 					code: "FORBIDDEN",
 					message: "This season is closed",
 				});
 			}

 			if (comp.scoreType !== "1-v-n-elo") {
 				throw new TRPCError({
 					code: "BAD_REQUEST",
 					message: "1-v-n games can only be recorded in 1-v-n-elo seasons",
 				});
 			}

 			const allIds = [input.winnerId, ...input.loserIds];
 			if (allIds.length < 2) {
 				throw new TRPCError({
 					code: "BAD_REQUEST",
 					message: "A 1-v-n game needs at least 2 players",
 				});
 			}

 			if (input.loserIds.includes(input.winnerId)) {
 				throw new TRPCError({
 					code: "BAD_REQUEST",
 					message: "Winner cannot also be a loser",
 				});
 			}

 			if (new Set(allIds).size !== allIds.length) {
 				throw new TRPCError({
 					code: "BAD_REQUEST",
 					message: "Duplicate players in game",
 				});
 			}

 			const seasonPlayers = await seasonPlayerRepository.findAll({
 				db: ctx.db,
 				seasonId: comp.id,
 			});
 			const validIds = new Set(seasonPlayers.map((p) => p.id));
 			if (!allIds.every((id) => validIds.has(id))) {
 				throw new TRPCError({
 					code: "BAD_REQUEST",
 					message: "All players must be in this season",
 				});
 			}

 			if (input.id) {
 				try {
 					await matchRepository.findById({
 						db: ctx.db,
 						matchId: input.id,
 						seasonId: comp.id,
 					});
 					throw new TRPCError({
 						code: "CONFLICT",
 						message: "A match with this ID already exists",
 					});
 				} catch (error) {
 					if (error instanceof TRPCError) throw error;
 				}
 			}

 			const createdMatch = await matchRepository.create({
 				db: ctx.db,
 				input: {
 					id: input.id,
 					seasonId: comp.id,
 					homeScore: 1,
 					awayScore: input.loserIds.length,
 					homeTeamPlayerIds: [input.winnerId],
 					awayTeamPlayerIds: input.loserIds,
 					userId: ctx.authentication.user.id,
 				},
 			});

 			return finalizeMatchCreation({
 				ctx,
 				seasonSlug: input.seasonSlug,
 				seasonId: comp.id,
 				createdMatch,
 				seasonPlayerIds: allIds,
 			});
 		}),

 	remove: seasonProcedure
 		.input(
 			z.object({
 				seasonSlug: z.string(),
 				matchId: z.string(),
 			})
 		)
 		.mutation(async ({ ctx, input }) => {
 			await matchRepository.remove({
 				db: ctx.db,
 				matchId: input.matchId,
 				seasonId: ctx.season.id,
 			});

 			const standings = await seasonPlayerRepository.getStanding({
 				db: ctx.db,
 				seasonId: ctx.season.id,
 			});

 			ctx.waitUntil(
 				broadcastSeasonEvent(ctx.env, ctx.organization.slug, input.seasonSlug, {
 					type: "match:delete",
 					data: {
 						matchId: input.matchId,
 						standings,
 					},
 					user: {
 						id: ctx.authentication.user.id,
 						name: ctx.authentication.user.name,
 					},
 				})
 			);

 			return { success: true };
 		}),

 	getById: seasonProcedure
 		.input(
 			z.object({
 				seasonSlug: z.string(),
 				matchId: z.string(),
 			})
 		)
 		.query(async ({ ctx, input }) => {
 			return matchRepository.getMatchWithPlayers({
 				db: ctx.db,
 				matchId: input.matchId,
 			});
 		}),

 	getLatest: seasonProcedure.query(async ({ ctx }) => {
 		const match = await matchRepository.findLatest({
 			db: ctx.db,
 			seasonId: ctx.season.id,
 		});

 		if (!match) return null;

 		return matchRepository.getMatchWithPlayers({
 			db: ctx.db,
 			matchId: match.id,
 		});
 	}),

 	getAll: seasonProcedure
 		.input(
 			z.object({
 				seasonSlug: z.string(),
 				limit: z.number().int().optional().default(30),
 				offset: z.number().int().optional().default(0),
 			})
 		)
 		.query(async ({ ctx, input }) => {
 			return matchRepository.getBySeasonId({
 				db: ctx.db,
 				seasonId: ctx.season.id,
 				limit: input.limit,
 				offset: input.offset,
 			});
 		}),
 } satisfies TRPCRouterRecord;

